{
  "imports": [
    "from decimal import Decimal",
    "from ledger.rounding import cash_round"
  ],
  "tests": [
    {
      "name": "test_cash_round_exact_half_rounds_up",
      "intent": "exact half rounds up to nearest step",
      "code": "# intent: exact half rounds up to nearest step\ndef test_cash_round_exact_half_rounds_up():\n    assert cash_round(Decimal('1.025')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_just_below_half_rounds_down",
      "intent": "value just below half rounds down",
      "code": "# intent: value just below half rounds down\ndef test_cash_round_just_below_half_rounds_down():\n    assert cash_round(Decimal('1.024')) == Decimal('1.00')\n"
    },
    {
      "name": "test_cash_round_just_above_half_rounds_up",
      "intent": "value just above half rounds up",
      "code": "# intent: value just above half rounds up\ndef test_cash_round_just_above_half_rounds_up():\n    assert cash_round(Decimal('1.026')) == Decimal('1.05')\n"
    },
    {
      "name": "test_cash_round_negative_exact_half_rounds_up",
      "intent": "negative exact half rounds up (towards positive infinity)",
      "code": "# intent: negative exact half rounds up (towards positive infinity)\ndef test_cash_round_negative_exact_half_rounds_up():\n    assert cash_round(Decimal('-1.025')) == Decimal('-1.00')\n"
    },
    {
      "name": "test_cash_round_zero_is_unchanged",
      "intent": "zero is already a multiple of any step",
      "code": "# intent: zero is already a multiple of any step\ndef test_cash_round_zero_is_unchanged():\n    assert cash_round(Decimal('0.00')) == Decimal('0.00')\n"
    },
    {
      "name": "test_cash_round_custom_step_exact_half_rounds_up",
      "intent": "custom step with exact half rounds up",
      "code": "# intent: custom step with exact half rounds up\ndef test_cash_round_custom_step_exact_half_rounds_up():\n    assert cash_round(Decimal('2.25'), Decimal('0.10')) == Decimal('2.30')\n"
    }
  ]
}
